const raw = $input.first().json;
let parsed;
try {
  parsed = typeof raw.designs === 'string' ? JSON.parse(raw.designs) : raw;
} catch (_) { parsed = raw; }

const designs = parsed.designs || (Array.isArray(parsed) ? parsed : [parsed]);
return designs.map(d => ({ json: d }));

